11	/**
12	 * requestId 幂等：同键同参返回首次结果（含失败首次结果）；同键异参 409 且不改变批次状态。
13	 */
14	class IdempotencyTest extends BaseApiTest {
15	
16	    private void seedOne(String declNo, String prefix) throws Exception {
17	        seedLibrary();
18	        postJson("/api/collect/customs",
19	                TestFixtures.customs(prefix + "-c", declNo, TestFixtures.P1, "1000", "20"), 200);
20	        postJson("/api/collect/invoices",
21	                TestFixtures.invoice(prefix + "-i", "INV-" + declNo, declNo,
22	                        TestFixtures.P1, "900"), 200);
23	    }
24	
25	    @Test
26	    void sameKeySameParamsReturnsFirstResult() throws Exception {
27	        seedOne("CD-IDEM", "idm");
28	        String body = TestFixtures.check("idem-chk", "B-IDEM", "2026-02-01", "CD-IDEM");
29	        JsonNode first = postJson("/api/batches/check", body, 200);
30	        JsonNode replay = postJson("/api/batches/check", body, 200);
31	        assertEquals(first.get("status").asText(), replay.get("status").asText());
32	        assertEquals(first.get("totalDeclaredTax").asText(), replay.get("totalDeclaredTax").asText());
33	
34	        // 申报也重放：两次均 DECLARED，批次仅冻结一次
35	        String declareBody = TestFixtures.declare("idem-decl", false);
36	        postJson("/api/batches/B-IDEM/declare", declareBody, 200);
37	        JsonNode replayDecl = postJson("/api/batches/B-IDEM/declare", declareBody, 200);
38	        assertEquals("DECLARED", replayDecl.get("status").asText());
39	    }
40	
41	    @Test
42	    void sameKeyDifferentParamsConflictsAndStateUnchanged() throws Exception {
43	        seedOne("CD-C1", "c1");
44	        seedOne("CD-C2", "c2");
45	        // 首次：批次 B-A 包含 CD-C1
46	        postJson("/api/batches/check",
47	                TestFixtures.check("shared-key", "B-A", "2026-02-01", "CD-C1"), 200);
48	        // 同 requestId 换成不同批次号/单证 -> 409
49	        JsonNode conflict = postJson("/api/batches/check",
50	                TestFixtures.check("shared-key", "B-B", "2026-02-01", "CD-C2"), 409);
51	        assertTrue(conflict.get("error").asText().contains("不同业务参数"));
52	
53	        // CD-C2 未被占用：B-B 未创建，CD-C2 仍可独立建批
54	        JsonNode b2 = postJson("/api/batches/check",
55	                TestFixtures.check("other-key", "B-B", "2026-02-01", "CD-C2"), 200);
56	        assertEquals("CHECKED", b2.get("status").asText());
57	        assertEquals("CHECKED", getJson("/api/batches/B-A", 200).get("status").asText());
58	    }
59	
60	    @Test
61	    void sameKeyReplaysFirstFailureToo() throws Exception {
62	        // 首次请求即失败（报关单不存在），同键重放得到相同 404 存档响应
63	        String body = TestFixtures.check("fail-key", "B-FAIL", "2026-02-01", "CD-NONE");
64	        JsonNode first = postJson("/api/batches/check", body, 404);
65	        JsonNode replay = postJson("/api/batches/check", body, 404);
66	        assertEquals(first.get("error").asText(), replay.get("error").asText());
67	        assertEquals(404, getRawStatus("/api/batches/B-FAIL"));
68	    }
69	
70	    private int getRawStatus(String path) throws Exception {
71	        return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(path))
72	                .andReturn().getResponse().getStatus();
73	    }
74	}
