package com.example.rebate.domain;

/**
 * 分批冲回单状态。
 *
 * <p>PENDING 待复核 → APPROVED 已批准（追缴中）/ REJECTED 已驳回（不占额）；
 * 追缴回执累计恰收齐批准金额后 APPROVED → COMPLETED（终态，只读）。</p>
 */
public enum ReversalStatus {

    /** 待复核：已提交未占用可冲额。 */
    PENDING,

    /** 已批准：同事务占用剩余可冲额并产生追缴明细，回执登记中。 */
    APPROVED,

    /** 已驳回：不占用任何可冲额，终态。 */
    REJECTED,

    /** 追缴完成：回执累计恰等于批准金额，只读，终态。 */
    COMPLETED
}

package com.example.rebate.domain;

import java.time.Instant;

/**
 * 追缴明细：冲回单批准时在同一事务内产生的独立明细。
 *
 * @param reversalId 所属冲回单 id（一张已批准冲回单恰好一条）
 * @param clawbackSerial 追缴独立流水号，与原核销国库流水互不影响
 * @param amountCents 批准追缴金额（正数整数分）
 * @param approvedAt 批准时刻（UTC）
 */
public record ClawbackDetail(
        Long id,
        Long reversalId,
        String clawbackSerial,
        long amountCents,
        Instant approvedAt) {
}

package com.example.rebate.domain;

import java.time.Instant;

/**
 * 追缴到账回执：独立流水号全局唯一，允许多笔部分到账。
 *
 * @param reversalId 所属（已批准）冲回单 id
 * @param receiptSerial 追缴回执独立流水号；同流水异金额拒绝，同流水同金额去重
 * @param amountCents 本笔实际收回金额（正数整数分）
 * @param receivedAt 到账登记时刻（UTC）
 */
public record ClawbackReceipt(
        Long id,
        Long reversalId,
        String receiptSerial,
        long amountCents,
        Instant receivedAt) {
}

